// =============================================================================
// Event payload
// =============================================================================

export type EventPayload<T extends EventName> = T extends keyof EventMetadataMap
  ? EventContext & {
      name: T;
      metadata: EventMetadataMap[T];
      eventKey?: string | null;
      occurredAt?: Date;
    }
  : EventContext & {
      name: T;
      metadata?: Record<string, never>;
      eventKey?: string | null;
      occurredAt?: Date;
    };

// =============================================================================
// Behavioral event payload
// =============================================================================

export type BehavioralEventPayload<T extends BehavioralEventName> =
  EventPayload<T>;
